import{_ as o}from"./chunks/run-changes.BxnGjCua.js";import{_ as h,C as t,o as l,c as d,j as a,a as c,E as n,a6 as s}from"./chunks/framework.CCKCzdWs.js";const u="/diagrams/baseline-ladder.svg",x=JSON.parse('{"title":"What changed in a run","description":"What changed in a run against its baseline: new failures, fixed tests, new flakes, the largest duration changes and the commits in between.","frontmatter":{"title":"What changed in a run","description":"What changed in a run against its baseline: new failures, fixed tests, new flakes, the largest duration changes and the commits in between.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/run-changes.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/run-changes.html"}],["meta",{"property":"og:title","content":"What changed in a run | Piwi for Playwright"}],["meta",{"property":"og:description","content":"What changed in a run against its baseline: new failures, fixed tests, new flakes, the largest duration changes and the commits in between."}]]},"headers":[],"relativePath":"features/run-changes.md","filePath":"features/run-changes.md","lastUpdated":1795796710000}'),g={name:"features/run-changes.md"};function f(m,e,p,b,w,y){const r=t("Needs"),i=t("DemoExamples");return l(),d("div",null,[e[0]||(e[0]=a("h1",{id:"what-changed-in-a-run",tabindex:"-1"},[c("What changed in a run "),a("a",{class:"header-anchor",href:"#what-changed-in-a-run","aria-label":'Permalink to "What changed in a run"'},"​")],-1)),n(r,{reporter:""}),e[1]||(e[1]=s('<p>The <strong>Changes</strong> tab on a run compares it against <strong>one baseline</strong> and tells you what moved: which tests newly started failing, which got fixed, and what landed between the two. It&#39;s the fastest way to answer &quot;did my push break this, or was it already red?&quot;</p><h2 id="the-baseline" tabindex="-1">The baseline <a class="header-anchor" href="#the-baseline" aria-label="Permalink to &quot;The baseline&quot;">​</a></h2><p>Every section reads the <strong>same baseline</strong>, so the &quot;new failures&quot; count is computed once and used throughout. The selector at the top says which run it is, which branch and environment that run is on, and <strong>why it was chosen</strong>.</p><p>By default the baseline is the <strong>last passing full run</strong>, chosen by environment first, then branch. The ladder is walked within the run&#39;s environment label first, then again without it. On each pass it takes the most recent passing run on the <strong>same branch</strong>, else on the <strong>base branch</strong> the run&#39;s branch forked from (the pull request&#39;s target branch when the reporter captured one, else the project&#39;s <a href="./branches.html#the-default-branch">default branch</a>), else on <strong>any branch</strong>. So a <code>staging</code> run on <code>feature/x</code> compares with the last passing <code>staging</code> run on <code>feature/x</code>, then the last passing <code>staging</code> run on <code>main</code>, then any passing <code>staging</code> run, and only then with a run from another environment. A run whose branch is unknown has only the any-branch rung; a run with no environment label walks the branch ladder once. A lab run (a probe or a Flake Lab experiment) is never a baseline. The line under the selector spells out the rung that applied, for example <em>&quot;No passing staging run exists on feature/x; the last passing run on the default branch main in staging.&quot;</em></p><figure><img src="'+u+'" alt="The baseline ladder: same branch, base branch, then any branch, first within the run&#39;s environment and then in any environment; with no passing run, the same rungs for the last failed run"><figcaption>The baseline rule: six rungs tried in order, the first with an earlier passing run giving the baseline.</figcaption></figure><p>The same baseline is what the run insights, the stored <a href="./flaky-tests.html#regression-signals">regression signals</a>, the <a href="./merge-gate.html">CI merge gate</a>, <a href="./pr-feedback.html">pull-request feedback</a>, the bisect window and the git diff behind an <a href="./ai-diagnosis.html#scm-grounded-context">AI diagnosis</a> compare against. The regression signals compare the last attempt of each test (of each repetition, with <code>--repeat-each</code>) with its outcome in the baseline in the same Playwright project, and are never set on an earlier attempt of a retried test.</p><h3 id="one-execution-s-baseline" tabindex="-1">One execution&#39;s baseline <a class="header-anchor" href="#one-execution-s-baseline" aria-label="Permalink to &quot;One execution&#39;s baseline&quot;">​</a></h3><p>The environment, visual and page diffs of one failing execution compare it with the same test&#39;s last passing execution on the same browser, in a shorter order: the same environment, then the same branch, then the most recent, with no base-branch rung. The page diff also prefers, right after the environment, a run on the same Playwright release (major and minor version), since ARIA snapshots can change from one version to the next (Playwright 1.65 leaves out text the browser does not render). When no passing run from the same environment exists, the card says which environment the baseline came from (<em>&quot;compared with a production run; no passing development run of this test exists&quot;</em>) and leaves the environment label out of the diff.</p><h3 id="when-no-earlier-run-passed" tabindex="-1">When no earlier run passed <a class="header-anchor" href="#when-no-earlier-run-passed" aria-label="Permalink to &quot;When no earlier run passed&quot;">​</a></h3><p>A project that has never had a green run still gets a comparison. When no earlier full run passed, the tab walks the same ladder again for the <strong>last failed run</strong> and says so: <em>&quot;No earlier full run passed; the last failed run on feature/x in staging.&quot;</em> The sections read the same way against it: <strong>New failures</strong> are the tests that passed in that run and fail here, <strong>Still failing</strong> the ones that failed in both. Timed-out and interrupted runs stopped before the suite ended, so they are never picked automatically.</p><p>Only the Changes tab and the MCP <code>get_run_insights</code> tool take a failed run. The stored regression signals, the <a href="/features/merge-gate.html">CI merge gate</a> and <a href="/features/pr-feedback.html">pull-request feedback</a> keep comparing with a passing run, so their verdicts never rest on a run that was itself red.</p><p>When nothing qualifies (the earlier runs are partial, timed out or interrupted), the tab says so and offers the earlier runs to pick from. On the project&#39;s first finished run, it says there is nothing earlier yet.</p><h3 id="picking-another-baseline" tabindex="-1">Picking another baseline <a class="header-anchor" href="#picking-another-baseline" aria-label="Permalink to &quot;Picking another baseline&quot;">​</a></h3><p>Two ways to compare against something else:</p><ul><li><strong>Base branch</strong> — take the baseline from one branch only: its last passing run, else its last failed run, same environment first. The list offers every branch with an earlier full run that passed or failed, so it appears once a branch other than this run&#39;s own has one. Deep-linkable as <code>?baseBranch=&lt;name&gt;</code>.</li><li><strong>Run</strong> — compare against one earlier run, whatever its branch, environment or outcome. The list shows the 50 runs before this one, each with its branch, environment, start time and outcome, partial runs marked; type a branch or environment name to filter it. Deep-linkable as <code>?baseline=&lt;runId&gt;</code>, so a link to a comparison reopens the same two runs. <strong>Previous run</strong> is the shortcut for the run just before this one.</li></ul><p><strong>Automatic</strong> returns to the default choice. The same options exist on the REST API (see the <a href="https://piwitests.dev/demo/settings/api" target="_blank" rel="noreferrer">API docs</a>), where <code>earlierRuns</code> lists the runs that can be passed as <code>baseline</code>, and on the MCP <code>get_run_insights</code> tool (<code>baseBranch</code>).</p><h2 id="what-it-shows" tabindex="-1">What it shows <a class="header-anchor" href="#what-it-shows" aria-label="Permalink to &quot;What it shows&quot;">​</a></h2><ul><li><strong>New failures</strong> — passed in the baseline, failing here.</li><li><strong>Fixed</strong> — failed in the baseline, passing here.</li><li><strong>Still failing</strong> — failing in both.</li><li><strong>Newly flaky / passed on retry</strong> — passed here after an earlier attempt failed. Of these, a test that passed at its first attempt in the baseline is also <a href="#what-newly-flaky-says-about-your-change">newly flaky</a>.</li><li><strong>Slower / faster</strong> — the ten largest duration changes each way.</li><li><strong>Commits since the baseline</strong> — the commit range, a copyable <code>git log</code> command and, when the SCM host is known, a link to the commits.</li><li><strong>Deployed to Staging</strong>, for a run of a <a href="./deployed-environments.html">deployed environment</a> — the application&#39;s commit each run tested, the application&#39;s commits between them, and the environment&#39;s deploy markers between the two runs.</li><li><strong>Environment changes</strong> — the fields that differ (environment, branch, CI provider, browsers, and the <a href="#shuffled-runs">test order</a> of a shuffled run), in <em>This run</em> / <em>Baseline</em> columns. The browsers are those of the Playwright projects each run ran: the ones <code>--project</code> selects, the projects they depend on, and their teardown projects.</li></ul><figure><img src="'+o+'" alt="Run Changes tab showing the baseline selector, the tests that newly started failing, the ones that got fixed, and the commits landed since the baseline"><figcaption>The Changes tab on a run, read against one baseline — new failures, fixed tests, and the commits landed since.</figcaption></figure><p>Comparing two runs is also how the <a href="./ui-overview.html#test-run-detail">run comparison</a> works: select two runs on the project&#39;s Runs tab and the newer one opens on its Changes tab with the older as its baseline.</p><h3 id="what-newly-flaky-says-about-your-change" tabindex="-1">What newly flaky says about your change <a class="header-anchor" href="#what-newly-flaky-says-about-your-change" aria-label="Permalink to &quot;What newly flaky says about your change&quot;">​</a></h3><p><strong>Newly flaky</strong> is a change between the two runs, as a new failure is: the test needed a retry here and passed at its first attempt in the baseline. It does not clear your change. A change can make a test flaky (a new race, a slower call, a shared state), and so can anything else that differs between the runs. Nor does it convict it: one first-attempt pass in the baseline is one sample, and a test that has been flaky for weeks passes first time often.</p><p>The test&#39;s own history settles it. A <a href="/guide/concepts.html#flaky-rate">flaky rate</a> near zero until this run points at the commits since the baseline; one that has been high for weeks points at a flake your run happened to meet, which <a href="./flaky-tests.html">Flaky tests</a> ranks and quarantines. The <a href="./merge-gate.html">CI merge gate</a> counts newly flaky tests apart from new regressions (<code>--max-new-flaky</code>), so a pipeline can hold a branch for either.</p><h2 id="shuffled-runs" tabindex="-1">Shuffled runs <a class="header-anchor" href="#shuffled-runs" aria-label="Permalink to &quot;Shuffled runs&quot;">​</a></h2><p>A test that fails only after another one depends on the order, and a suite run in the same order every time shows the same neighbor every time, which leaves the flaky test&#39;s <a href="./flaky-tests.html#suspects"><strong>Before</strong> suspect</a> nothing to compare. Playwright 1.64&#39;s <code>--shuffle</code> schedules test files, and the tests of files in parallel mode, in a random order, and the run keeps its seed: the run&#39;s <strong>Details</strong> shows it as <strong>Order</strong>, and clicking the seed copies <code>--shuffle &lt;seed&gt;</code>, which runs the same tests on the same workers in the same order again. Against a baseline that was not shuffled, or the other way round, the Changes tab lists the <strong>Test order</strong> under Environment changes.</p><h2 id="try-it-in-the-demo" tabindex="-1">Try it in the demo <a class="header-anchor" href="#try-it-in-the-demo" aria-label="Permalink to &quot;Try it in the demo&quot;">​</a></h2>',26)),n(i),e[2]||(e[2]=s('<h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/recipes/regression-or-flaky.html">Regression or flake?</a>: the Changes tab, used to decide whether one red test is new</li><li><a href="./branches.html#branch-aware-baselines">Branches</a> — why the default baseline is the same-branch run</li><li><a href="./flaky-tests.html">Flaky tests</a> — the per-project flaky, regression and spec-health signals</li><li><a href="./failure-clusters.html">Failure clusters</a> — the failures grouped by cause</li><li><a href="./timeline-markers.html">Timeline markers</a> — annotate the trend charts with real-world events</li></ul>',2))])}const _=h(g,[["render",f]]);export{x as __pageData,_ as default};
